function App() {
  useEffect(() => {
    const lenis = new Lenis({ duration: 1.15, smoothWheel: true, touchMultiplier: 1.05 });
    let raf = 0;
    const render = (time: number) => { lenis.raf(time); raf = requestAnimationFrame(render); };
    raf = requestAnimationFrame(render);
    return () => { cancelAnimationFrame(raf); lenis.destroy(); };
  }, []);

  const go = (id: string) => { const target = document.querySelector(id); if (target) target.scrollIntoView({ behavior: 'smooth', block: 'start' }); };
  const items = [
    { icon: <VscHome size={18} />, label: 'Home', onClick: () => go('#home') },
    { icon: <VscArchive size={18} />, label: 'Archive', onClick: () => go('#work') },
    { icon: <VscAccount size={18} />, label: 'Profile', onClick: () => go('#about') },
    { icon: <VscSettingsGear size={18} />, label: 'Settings', onClick: () => go('#resume') },
  ];

  return (
    <main>
      <header className="reference-nav"><div className="reference-nav-inner"><button className="reference-brand" onClick={() => go('#home')}><strong>Surya Kiran</strong><span className="reference-brand-divider" /><span>India</span></button><nav><button onClick={() => go('#art')}>Art</button><button onClick={() => go('#about')}>About Me</button><a className="resume-nav-link" href="/surya-portfolio/resume/">Resume</a></nav></div></header>
      <section id="home" className="reference-home"><div className="reference-home-viewport"><div className="reference-home-stage"><div className="reference-portrait" aria-label="Portrait of Surya Kiran"><img className="reference-portrait-image" src={portraitUrl} alt="Surya Kiran" /></div><div className="reference-fade" /><div className="reference-head-animation" aria-hidden="true"><svg viewBox="0 0 260 130" className="head-animation-svg"><text className="head-animation-text" x="18" y="88">ART</text></svg></div><div className="reference-hero-copy"><h1><span>Designing how products earn trust,</span><span>across <em>visual, product &amp; growth.</em></span></h1><button className="reference-work" onClick={() => go('#work')}>See my work</button></div></div></div></section>
      <section id="work" className="reference-work-section"><div className="work-intro"><p>SELECTED WORK</p></div><GenesisCard /><ComskiCard /><LaundroMartCard /></section>
      <section className="other-reference" aria-label="Other Projects">
        <h2 className="other-reference-heading">Other Projects</h2>
        <div className="other-reference-grid">
          <a className="reference-card-link" href="/surya-portfolio/toniq-ai.html" aria-label="Toniq AI — Virtual networking was spatially broken. Designed a 2D event platform and AI layer that gives people context, conversation, and connection.">
            <article className="other-reference-card reference-artwork-card" aria-label="Toniq AI project">
              <img src="data:image/webp;base64," alt="Toniq AI — Virtual networking was spatially broken. Designed a 2D event platform and AI layer that gives people context, conversation, and connection." />
            </article>
          </a>
          <a className="reference-card-link" href="https://www.helloayushi.com/case-study/shine" aria-label="Shi+ne — A productivity desk companion that celebrates every Notion task you finish. Smart object built on ESP32, a touch LCD, and a servo-driven flower.">
            <article className="other-reference-card reference-artwork-card" aria-label="Shine desk buddy project">
              <img src="data:image/webp;base64," alt="Shi+ne — A productivity desk companion that celebrates every Notion task you finish. Smart object built on ESP32, a touch LCD, and a servo-driven flower." />
            </article>
          </a>
        </div>
      </section>
      <ToolsWorkflow />
      <footer className="reference-footer"><h2>Every pixel here was a decision.</h2><p>Every word, a choice. Thanks for seeing it.</p><div className="footer-icons"><Linkedin/><FileText/><Github/></div><div className="footer-line" /><div className="footer-mark">≈≈≈</div><strong>Surya Kiran © 2026</strong></footer>
      <div className="portfolio-dock"><Dock items={items} panelHeight={70} baseItemSize={50} magnification={70} /></div><button className="to-top" onClick={() => go('#home')} aria-label="Back to top"><ArrowUp size={19}/></button>
    </main>
  );
}

createRoot(document.getElementById('root')!).render(<React.StrictMode><App /></React.StrictMode>);
